import java.time.*;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate awal = LocalDate.of(2026, 1, 20);
        LocalDate akhir = LocalDate.of(2026, 3, 5);

        Period p = Period.between(awal, akhir);
        System.out.println(p);
        System.out.println(p.getDays());
        System.out.println(ChronoUnit.DAYS.between(awal, akhir));
        System.out.println(ChronoUnit.DAYS.between(akhir, awal));
    }
}

